import { useEffect, useState } from "react";
import { Chapter, Question, Page } from "../types";
import data from "../data.json";
import { getQuestionLayout } from "../utils/utils";

interface UseQuestionDataReturn {
    questions: Question[] | null;
    pages: Page[];
    chapters: Chapter[];
}

export function useQuestionData(): UseQuestionDataReturn {
    const [questions, setQuestions] = useState<Question[] | null>(null)
    const [pages, setPages] = useState<Page[]>([]);
    const [chapters, setChapters] = useState<Chapter[]>([]);

    useEffect(() => {
        if (!data) {
            return;
        }

        const result = [];
        const pagesResult: Page[] = [];
        const chaptersResult: Chapter[] = [];

        let globalQuestionIndex = 0; // Global index of question, so it can be used for navigation
        for (const page of data) {
            pagesResult.push({
                page: page.page,
                questionCount: page.answers.length,
                layout: getQuestionLayout(page.splitRows),
                questionIndex: globalQuestionIndex,
            })

            if (page.chapter) {
                chaptersResult.push({
                    name: page.chapter,
                    page: page.page,
                    questionIndex: globalQuestionIndex,
                });
            }

            let questionIndex = 0;
            for (const question of page.answers) {
                questionIndex++;
                result.push({
                    page: page.page,
                    question: questionIndex,
                    answer: question,
                    options: page.options[questionIndex - 1],
                });
                globalQuestionIndex++;
            }
        }

        setPages(pagesResult);
        setQuestions(result);
        setChapters(chaptersResult);
    }, []);

    return {
        questions: questions,
        pages: pages,
        chapters: chapters,
    };
}
