export function MenuIcon() {
    return (
      <>
        {[1, 2, 3].map(el => (
          <div
            key={el}
            style={{
                width: "21px",
                height: "3px",
                backgroundColor: "rgba(255, 255, 255, 0.87)",
                margin: "4px 0"
            }}
          />
        ))}
      </>
    )
  }
  