import classNames from "classnames";

import { useImage } from "../hooks/useImage";
import { Page } from "../types";

import '../App.css'

interface QuestionImageProps {
  page: number | null;
  question: number | null;
  pages: Page[];
}

export function QuestionImage({ page, question, pages }: QuestionImageProps) {
    const { isLoading, hideLeft, hideRight } = useImage({
        page: page,
        question: question,
        pages: pages,
    });

    return (
        <div className="question-description">
            <div id="left-image" className={classNames({ hide: hideLeft })} />
                <div id="right-image" className={classNames({ hide: hideRight })} />
                <div className={classNames("loader", { show: isLoading })}>
                <div className="loading-indicator" />
            </div>
        </div>
    );
}
